window.futvizVista("mapa-tiros","<div class=\"rx-mount\" data-rx=\"tiros\" data-rx-id=\"mapa-tiros\" style=\"min-height:520px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"mapa-tiros\"]={\"id\":\"mapa-tiros\",\"titulo\":\"Mapa de calor de los tiros\",\"bajada\":\"Cada celda es el % de los tiros que sali\u00f3 de ah\u00ed, no un conteo: oscuro es una parte grande del total.\",\"pregunta\":\"\u00bfDesde d\u00f3nde se tira en las 5 ligas?\",\"tabla\":\"tiros\",\"fuente\":\"Understat\",\"enCurso\":{\"2026-27\":9},\"queMirar\":\"De d\u00f3nde se tira: el color reparte el 100% de los tiros que ves entre celdas de 2\u00d72 m.\\n- El mapa mira hacia la porter\u00eda: la l\u00ednea de fondo es el borde de arriba\\n- Celda oscura: de ah\u00ed sali\u00f3 una parte grande de los tiros, no \u00abmuchos\u00bb tiros\\n- Pasa el mouse sobre una celda para ver cu\u00e1ntos tiros salieron y cu\u00e1ntos fueron gol\\n- \u00abVer\u00bb cambia el mapa por los tiros de un jugador o de un equipo, uno por uno: lleno si fue gol, m\u00e1s grande cuanto m\u00e1s val\u00eda\"};</script>");